ruleContent:
@js:
let d={};try{d=JSON.parse(result)}catch(e){d={kind:'error',title:'页面解析失败',summary:String(e)}}
function esc(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;')}
const RAW='https://raw.githubusercontent.com/huoguotiankong/source-core-8d7/main/';
const CDN='https://cdn.jsdelivr.net/gh/huoguotiankong/source-core-8d7@main/';
let title=d.title||'🌈 阅读书源仓库',summary=d.summary||'',kind=d.kind||'info',buttons='',badges='',sections='';
(Array.isArray(d.badges)?d.badges:[]).forEach(x=>badges+='<span>'+esc(x)+'</span>');
(Array.isArray(d.sections)?d.sections:[]).forEach(x=>sections+='<div class=\"card\"><b>'+esc(x.title||'说明')+'</b><p>'+esc(x.text||'').replace(/\n/g,'<br>')+'</p></div>');
function btn(text,url,alt){return '<a class=\"btn '+(alt?'alt':'')+'\" href=\"'+esc(url)+'\">'+esc(text)+'</a>'}
if(kind==='source'&&d.sourceUrl){buttons=btn('从 GitHub 导入 / 更新书源','legado://import/importonline?src='+d.sourceUrl,false);if(d.backupUrl)buttons+=btn('备用线路导入','legado://import/importonline?src='+d.backupUrl,true)}
if(kind==='bundle'&&d.bundlePath){let u=RAW+d.bundlePath,b=CDN+d.bundlePath;buttons=btn('主线路批量导入','legado://import/importonline?src='+u,false)+btn('备用线路批量导入','legado://import/importonline?src='+b,true)}
if(kind==='rss'&&d.rssUrl){buttons=btn('重新导入 / 更新仓库订阅源','legado://import/rssSource?src='+d.rssUrl,false)}
result='<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><style>:root{color-scheme:light dark;--bg:#f6f7fb;--card:#fff;--text:#202532;--muted:#6f7788;--line:#e4e7ee;--p1:#596cff;--p2:#965cff}@media(prefers-color-scheme:dark){:root{--bg:#11141b;--card:#1a1f29;--text:#eef2f8;--muted:#9aa4b5;--line:#2c3340}}*{box-sizing:border-box}body{margin:0;padding:18px;background:var(--bg);color:var(--text);font-family:sans-serif}.hero{padding:22px;border-radius:20px;color:#fff;background:linear-gradient(135deg,var(--p1),var(--p2))}h1{margin:0 0 8px;font-size:23px}.hero p{margin:0;line-height:1.6}.badges{margin-top:12px}.badges span{display:inline-block;margin:3px 5px 0 0;padding:5px 9px;border-radius:999px;background:rgba(255,255,255,.18);font-size:12px}.card{margin-top:14px;padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.card p{color:var(--muted);line-height:1.7}.btn{display:block;margin-top:14px;padding:14px;text-align:center;text-decoration:none;color:#fff;font-weight:bold;border-radius:14px;background:linear-gradient(135deg,var(--p1),var(--p2))}.btn.alt{background:var(--card);color:var(--p1);border:1px solid var(--p1)}.foot{text-align:center;color:var(--muted);font-size:12px;padding:18px}</style></head><body><div class=\"hero\"><h1>'+esc(title)+'</h1><p>'+esc(summary)+'</p><div class=\"badges\">'+badges+'</div></div>'+sections+buttons+'<div class=\"foot\">🌈 阅读书源仓库 · 0.3.0-beta10</div></body></html>';
result;
